use PHPUnit\Framework\TestCase;
final class CreatorCampaignBudgetsV7ContractTest extends TestCase{private string $r;protected function setUp():void{$this->r=dirname(__DIR__,2);}public function testLedgerAndBoundaries():void{$s=file_get_contents($this->r.'/database/20260722_creator_campaign_budget_controls_v7_single_install.sql');self::assertStringContainsString('available_delta_minor',$s);self::assertStringContainsString('uq_cc_budget_reservation_earning',$s);self::assertStringNotContainsString('creator_campaign_payouts',$s);}public function testAtomicLifecycle():void{$s=file_get_contents($this->r.'/includes/creator-campaigns/budget-service.php');self::assertStringContainsString('mg_creator_campaign_assert_transaction_boundary',$s);self::assertStringContainsString("'commit'",$s);self::assertStringContainsString("'release'",$s);}public function testMerchantScope():void{$a=file_get_contents($this->r.'/api/merchant/creator-campaign-budgets.php');$s=file_get_contents($this->r.'/includes/creator-campaigns/budget-service.php');self::assertStringContainsString('mg_require_csrf_for_write',$a);self::assertStringContainsString('merchant.creator_budgets.manage',$s);}}
